const alert = $json;

return {
  json: {
    alert_data: JSON.stringify(alert, null, 2),

    evidence_request: `
Investigate this alert and identify relevant evidence.

Alert:
${JSON.stringify(alert, null, 2)}

Analyze:
1. Evidence supporting the alert
2. Possible cause
3. Related events or indicators
4. Signs that it could be a false positive
5. Important findings

Do not invent evidence. If evidence is unavailable, clearly state that.
`
  }
};

return $input.all().map(item => {
  const json = item.json;
  const agent1Analysis = json.alert_analysis || json.output || "No analysis provided from Agent 1.";
  const agent2Evidence = json.evidence_assessment || json.output || "No evidence provided from Agent 2.";

  return {
    json: {
      ...json,
      risk_prompt: `You are the Risk Assessment Agent in a cybersecurity alert analysis system.

Your job is to assess the risk of a security alert using the available alert information, classification, and investigation evidence.

=== INPUT DATA FOR THIS ALERT ===
ALERT & AGENT 1 ANALYSIS:
${agent1Analysis}

AGENT 2 EVIDENCE ASSESSMENT:
${agent2Evidence}

=== EVALUATION CRITERIA ===
Evaluate:
1. Severity
2. Likelihood of a real attack
3. Potential impact
4. Strength of evidence
5. Affected asset or user
6. Urgency of response

Assign a risk level:
- LOW: Minor or likely harmless activity with little evidence of compromise.
- MEDIUM: Suspicious activity that requires investigation but has limited impact.
- HIGH: Strong evidence of malicious activity or potentially serious compromise.
- CRITICAL: Confirmed or highly likely serious attack involving major systems, sensitive data, or immediate danger.

=== CONSTRAINTS ===
- Do not invent information.
- Base the risk assessment ONLY on the provided alert and evidence.

=== OUTPUT FORMAT ===
Return:
- Risk Level: [LOW / MEDIUM / HIGH / CRITICAL]
- Risk Score: [0 to 100]
- Likelihood: [Low / Medium / High]
- Potential Impact: [Low / Medium / High / Critical]
- Risk Factors: [Brief summary]
- Recommended Action: [Action steps]
- Reason for Risk Level: [Justification]`
    }
  };
});

// 1. Get input text from the Decision Manager Agent
const inputItem = $input.first();
let rawOutput = inputItem.json.output || inputItem.json.text || inputItem.json.report_text || "";

// Clean up Markdown code block wrappers if present (e.g. ```json ... ```)
if (typeof rawOutput === 'string') {
  rawOutput = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();
}

let alertsArray = [];

// 2. Parse the output into a native JavaScript array
try {
  if (typeof rawOutput === 'string') {
    alertsArray = JSON.parse(rawOutput);
  } else if (Array.isArray(rawOutput)) {
    alertsArray = rawOutput;
  }
} catch (error) {
  // Fallback if parsing fails
  throw new Error("Decision Manager did not output valid JSON array: " + error.message);
}

// 3. Map each alert into an isolated n8n item with routing flags
return alertsArray.map(alert => {
  const severity = (alert.severity || "UNKNOWN").toUpperCase();
  const isHighOrCritical = (severity === "HIGH" || severity === "CRITICAL");

  return {
    json: {
      alert_id: alert.alert_id || "UNKNOWN",
      severity: severity,
      is_high_or_critical: isHighOrCritical,
      is_critical: severity === "CRITICAL",
      is_high: severity === "HIGH",
      is_medium: severity === "MEDIUM",
      is_low: severity === "LOW",
      target_entity: alert.target_entity || "",
      asset_sensitivity: alert.asset_sensitivity || "",
      summary: alert.summary || "",
      recommendation: alert.recommendation || "",
      report_text: `Alert ${alert.alert_id} [${severity}]: ${alert.summary}`
    }
  };
});

const items = $input.all();

return items.map(item => {
  // 1. Get raw input or parsed object
  let data = item.json;

  // Handle case where agent output is wrapped inside a string
  if (data.output && typeof data.output === 'string') {
    try {
      const cleaned = data.output.replace(/```json/gi, '').replace(/```/g, '').trim();
      data = JSON.parse(cleaned);
    } catch (e) {
      // Retain item.json if string parsing fails
    }
  }

  // Handle array wrapping if nested
  if (Array.isArray(data)) {
    data = data[0] || {};
  }

  // 2. Extract JSON fields directly with fallback mapping
  const severity = (data.severity || data.risk_level || "UNKNOWN").toUpperCase();

  return {
    json: {
      alert_id: data.alert_id || "",
      timestamp: data.timestamp || "Pending",
      alert_type: data.alert_type || data.risk_factors || "",
      user_asset: data.target_entity || data.user_asset || "",
      role_dept: data.role_dept || "",
      access_level: data.access_level || "",
      business_importance: data.asset_sensitivity || data.business_importance || "",
      data_sensitivity: data.data_sensitivity || "",
      supporting_logs: data.supporting_logs || "",
      key_evidence: data.key_evidence || data.risk_factors || "",
      business_context: data.business_context || data.reasoning || "",
      severity: severity,
      risk_justification: data.risk_justification || data.reasoning || "",
      system_recommendation: data.system_recommendation || data.recommended_action || "",
      human_review_required: data.human_review_required !== undefined ? String(data.human_review_required) : "",
      mandatory_reason: data.mandatory_reason || data.reasoning || ""
    }
  };
});

const items = $input.all();

// Combine all individual report texts into a single string
const aggregatedReports = items.map((item, index) => {
  const data = item.json;

  // Use report_text if available, or build individual record text
  if (data.report_text) {
    return `=== ALERT ${index + 1} OF ${items.length} ===\n${data.report_text}`;
  }

  return `=== ALERT ${index + 1} OF ${items.length} ===
Alert ID          : ${data.alert_id || 'N/A'}
Severity          : ${data.severity || 'N/A'}
Alert Type        : ${data.alert_type || 'N/A'}
Target Entity     : ${data.user_asset || 'N/A'}
Key Evidence      : ${data.key_evidence || 'N/A'}
Recommendation    : ${data.system_recommendation || 'N/A'}`;
}).join('\n\n======================================================================\n\n');

// Return as a single n8n item
return [{
  json: {
    total_alerts: items.length,
    combined_message: aggregatedReports
  }
}];

// Collect raw text across ALL incoming items (handles single or multi-item inputs)
let fullRawText = "";

for (const item of $input.all()) {
  const text = item.json.output || item.json.text || item.json.report_text || item.json.message || "";
  if (typeof text === 'string') {
    fullRawText += text + "\n\n";
  } else if (typeof text === 'object') {
    fullRawText += JSON.stringify(text) + "\n\n";
  }
}

const parsedAlerts = [];
const processedIds = new Set();

// Helper function to extract regex matches safely
const extractField = (block, pattern) => {
  const match = block.match(pattern);
  return match ? match[1].trim() : "";
};

// 1. Regex to target every individual INVESTIGATION RECORD block
const recordRegex = /INVESTIGATION RECORD[\s\S]*?(?=(?:INVESTIGATION RECORD|Severity:\s*(?:CRITICAL|HIGH|MEDIUM|LOW)|$))/gi;
const blocks = fullRawText.match(recordRegex) || [];

for (const block of blocks) {
  const alertRef = extractField(block, /Alert Reference\s*:\s*\[?([^\]\n]+)\]?/i);
  const idMatch = alertRef.match(/(A\d+)/i) || block.match(/\b(A0*\d+)\b/i);

  if (idMatch && idMatch[1]) {
    const alertId = idMatch[1].toUpperCase();

    if (!processedIds.has(alertId)) {
      processedIds.add(alertId);

      // Parse piped headers
      const refParts = alertRef.split('|').map(s => s.trim());
      const timestamp = refParts[1] || "";
      const alertType = refParts[2] || "";

      const targetEntity = extractField(block, /Target Entity\s*:\s*\[?([^\]\n]+)\]?/i);
      const targetParts = targetEntity.split('|').map(s => s.trim());
      const userAsset = targetParts[0] || "";
      const roleDept = targetParts[1] || "";
      const accessLevel = targetParts[2] || "";

      const assetSens = extractField(block, /Asset Sensitivity\s*:\s*\[?([^\]\n]+)\]?/i);
      const sensParts = assetSens.split('|').map(s => s.trim());
      const businessImportance = sensParts[0] || "";
      const dataSensitivity = sensParts[1] || "";

      // Parse standard investigation fields
      const supportingLogs = extractField(block, /Supporting Logs Used\s*:\s*\[?([^\]\n]+)\]?/i);
      const keyEvidence = extractField(block, /Key Evidence\s*:\s*\[?([^\]\n]+)\]?/i);
      const businessContext = extractField(block, /Business Context\s*:\s*\[?([^\]\n]+)\]?/i);
      const riskJustification = extractField(block, /Risk Justification\s*:\s*\[?([^\]\n]+)\]?/i);
      const systemRecommendation = extractField(block, /System Recommendation\s*:\s*\[?([^\]\n]+)\]?/i);
      const humanReviewRequired = extractField(block, /Human Review Required\s*:\s*\[?([^\]\n]+)\]?/i);
      const mandatoryReason = extractField(block, /Mandatory Reason\s*:\s*\[?([^\]\n]+)\]?/i);

      // Parse severity
      const severityMatch = block.match(/Severity Level\s*:\s*(CRITICAL|HIGH|MEDIUM|LOW)/i) || 
                            block.match(/Severity\s*:\s*(CRITICAL|HIGH|MEDIUM|LOW)/i);
      const severity = severityMatch ? severityMatch[1].toUpperCase() : "MEDIUM";
      const isHighOrCritical = (severity === "HIGH" || severity === "CRITICAL");

      parsedAlerts.push({
        json: {
          alert_id: alertId,
          timestamp: timestamp,
          alert_type: alertType,
          user_asset: userAsset,
          role_dept: roleDept,
          access_level: accessLevel,
          business_importance: businessImportance,
          data_sensitivity: dataSensitivity,
          supporting_logs: supportingLogs,
          key_evidence: keyEvidence,
          business_context: businessContext,
          severity: severity,
          risk_justification: riskJustification,
          system_recommendation: systemRecommendation,
          human_review_required: humanReviewRequired,
          mandatory_reason: mandatoryReason,
          is_high_or_critical: isHighOrCritical,
          is_critical: severity === "CRITICAL",
          is_high: severity === "HIGH",
          is_medium: severity === "MEDIUM",
          is_low: severity === "LOW",
          report_text: block.trim()
        }
      });
    }
  }
}

// 2. Safety Net: Ensure all 12 IDs (A001 through A012) exist as individual n8n items
const expectedIds = ["A001", "A002", "A003", "A004", "A005", "A006", "A007", "A008", "A009", "A010", "A011", "A012"];

for (const id of expectedIds) {
  if (!processedIds.has(id)) {
    const snippetRegex = new RegExp(`(?:.*${id}.*){1,4}`, 'gi');
    const snippetMatch = fullRawText.match(snippetRegex);
    const reportText = snippetMatch ? snippetMatch.join('\n') : `Alert ${id}: Log details missing or undefined in report payload.`;

    const localSevMatch = reportText.match(/(CRITICAL|HIGH|MEDIUM|LOW)/i);
    const severity = localSevMatch ? localSevMatch[1].toUpperCase() : "MEDIUM";
    const isHighOrCritical = (severity === "HIGH" || severity === "CRITICAL");

    parsedAlerts.push({
      json: {
        alert_id: id,
        timestamp: "N/A",
        alert_type: "Unknown",
        user_asset: "Unknown",
        role_dept: "Unknown",
        access_level: "Unknown",
        business_importance: "Unknown",
        data_sensitivity: "Unknown",
        supporting_logs: "None provided",
        key_evidence: "No details extracted.",
        business_context: "Incomplete log payload.",
        severity: severity,
        risk_justification: "Incomplete alert data.",
        system_recommendation: "Investigate log pipeline for missing data.",
        human_review_required: "YES",
        mandatory_reason: "Missing telemetry.",
        is_high_or_critical: isHighOrCritical,
        is_critical: severity === "CRITICAL",
        is_high: severity === "HIGH",
        is_medium: severity === "MEDIUM",
        is_low: severity === "LOW",
        report_text: reportText.trim()
      }
    });
  }
}

// Sort items cleanly from A001 to A012
parsedAlerts.sort((a, b) => a.json.alert_id.localeCompare(b.json.alert_id, undefined, { numeric: true }));

return parsedAlerts;
